func (f *fakeDB) ListWorkspaces(ctx context.Context) ([]database.Workspace, error) {
	if f.listWSErr != nil {
		return nil, f.listWSErr
	}
	ac, hasAuth := authmw.FromContext(ctx)
	if !hasAuth {
		return f.workspaces, nil
	}
	if len(ac.AccessibleWorkspaceIDs) == 0 {
		return []database.Workspace{}, nil
	}
	allowed := make(map[string]struct{}, len(ac.AccessibleWorkspaceIDs))
	for _, id := range ac.AccessibleWorkspaceIDs {
		allowed[id] = struct{}{}
	}
	out := make([]database.Workspace, 0, len(f.workspaces))
	for _, w := range f.workspaces {
		if _, ok := allowed[database.UUIDString(w.ID)]; ok {
			out = append(out, w)
		}
	}
	return out, nil
}

func (f *fakeDB) GetWorkspace(ctx context.Context, workspaceID string) (database.Workspace, error) {
	if f.getWSErr != nil {
		return database.Workspace{}, f.getWSErr
	}
	ac, hasAuth := authmw.FromContext(ctx)
	if hasAuth {
		accessible := false
		for _, id := range ac.AccessibleWorkspaceIDs {
			if id == workspaceID {
				accessible = true
				break
			}
		}
		if !accessible {
			return database.Workspace{}, database.ErrNotFound
		}
	}
	for _, w := range f.workspaces {
		if database.UUIDString(w.ID) == workspaceID {
			return w, nil
		}
	}
	return database.Workspace{}, database.ErrNotFound
}

