func TestListActivity_ClientAudience_FiltersAllowlist(t *testing.T) {
	ws := makeUUID()
	db := &fakeDB{
		workspaces: []database.Workspace{ws},
		activity: []database.WorkspaceActivityEvent{
			makeActivity("created"),
			makeActivity("claimed"),        // filtered
