			makeActivity("started"),
			makeActivity("reviewer_started"), // filtered
			makeActivity("fix_started"),      // filtered
			makeActivity("work_phase_complete"),
			makeActivity("review_blocked"), // filtered
			makeActivity("retried"),        // filtered
			makeActivity("done"),
			makeActivity("blocked"),
			makeActivity("reviewer_complete"),
			makeActivity("ready"),
			makeActivity("cancelled"),
		},
	}
	svc := newService(db, &fakeAdapter{})

	events, se := svc.ListActivity(context.Background(), testWSID, domain.ActivityScope{Audience: "client"})
	if se != (domain.SourceError{}) {
		t.Fatalf("unexpected error: %v", se)
	}

	allowedLabels := map[string]bool{
		"Created": true, "Ready": true, "Started": true,
		"Progress": true, "Completed": true, "Blocked": true,
		"Reviewed": true, "Cancelled": true,
	}
	if len(events) != len(allowedLabels) {
		t.Fatalf("expected %d events, got %d: %v", len(allowedLabels), len(events), events)
